import fs from 'node:fs';
import assert from 'node:assert/strict';
import test from 'node:test';
import katex from 'katex';
import {blocks,block,visit,find} from '../../scripts/booklet/layout-repair-common-20261004.mjs';
import {teachingLabels} from '../../src/lib/booklet-labels.js';
import {combinedExampleTikz} from '../../src/lib/booklet-preview.js';
const fixtures=JSON.parse(fs.readFileSync(new URL('../fixtures/booklets/layout-audit-20261004/approved-blocks.json',import.meta.url)));
const nativeIds=p=>{const result=new Set();for(const b of blocks(p))visit(b,n=>{if(n.id)result.add(n.id);});return result;};
const answers=p=>{const result=new Map();function walk(n){if(!n||typeof n!=='object')return;if(n.id&&n.answer)result.set(n.id,n.answer);for(const [k,v]of Object.entries(n))if(!['sourceReview','sourceAtom','answer','spec'].includes(k))Array.isArray(v)?v.forEach(walk):walk(v);}walk(p.sections);return result;};
function estimates(p){return blocks(p).flatMap(b=>b.sourceReview?.workingSpaceEstimate?.estimates??[]);}
export function registerRepairTests(cause,repair,projects){
 test(cause+': approved content, answers and estimates survive; repeat run is inert',()=>{for(const id of projects){const source=structuredClone(fixtures[id]);const sentinel={id:'unapproved-sentinel',type:'rich-text',content:'Retain this unapproved block.',sourceReview:{intentionalDepartures:[{reason:'Local exception'}]}};source.sections[0].blocks.push(sentinel);const before=JSON.stringify(source),r=repair(source);assert.equal(JSON.stringify(source),before,'does not mutate input');assert.deepEqual(block(r.project,sentinel.id),sentinel,'does not migrate unrelated blocks');assert.deepEqual(repair(r.project).project,r.project,'idempotent');assert.equal(repair(r.project).records.length,0);
 const live=nativeIds(r.project),retired=new Set(blocks(r.project).flatMap(b=>b.sourceReview?.layoutRepairProvenance?.retainedWrapperIds??[]));for(const old of nativeIds(source))assert.ok(live.has(old)||retired.has(old),'retained ID '+id+'/'+old);
 const now=answers(r.project);for(const [target,answer]of answers(source)){if(cause==='tax-paired'&&target==='p61-charlie-response'){assert.deepEqual(block(r.project,'p61-example-block').sourceReview.layoutRepairProvenance.previousResponseAnswer,answer);const all=blocks(r.project).flatMap(b=>{const out=[];visit(b.content,n=>{if(n.answer?.worked?.blocks)out.push(...n.answer.worked.blocks);});return out;});for(const paragraph of answer.worked.blocks)assert.ok(all.some(x=>JSON.stringify(x)===JSON.stringify(paragraph)),'controlled worked line retained '+paragraph.id);}else assert.deepEqual(now.get(target),answer,'answer preserved '+target);}
 const afterEstimates=estimates(r.project);for(const estimate of estimates(source))assert.ok(afterEstimates.some(x=>JSON.stringify(x)===JSON.stringify(estimate)),'estimate preserved '+estimate.targetId);
 }});
 test(cause+': protected project is unchanged',()=>{const source=structuredClone(fixtures[projects[0]]);source.id='unapproved-project';assert.deepEqual(repair(source),{project:source,records:[]});});
 test(cause+': intended printed behaviour',()=>{
 const repaired=id=>repair(structuredClone(fixtures[id])).project;
 if(cause==='paired-preset'){const p=repaired('rates-v1'),b=block(p,'p36-example-group');assert.equal(b.content.columns,2);assert.equal(b.content.children.length,6);assert.deepEqual(b.content.children.filter((_,i)=>i%2===1).map(x=>x.id),['p36-your-turn-speed','p36-your-turn-distance','p36-your-turn-time']);assert.equal(b.content.prompt.blocks[0].rows.length,1);assert.equal(block(p,'p57-related-rates-coffee-fuel-row'),undefined);const length=block(repaired('length-v1'),'p45-diameter-turn-block');for(const response of length.sourceReview.responses??[]){const binding=response.promptBinding;if(binding?.ownerId==='p45-diameter-turn')assert.equal(binding.path,'/prompt/blocks/0/inlines/0');}}
 if(cause==='one-to-three-paired'){const p=repaired('solve-2-step-equations-v1');for(const id of ['p59-example-group','p60-teaching']){const b=block(p,id);assert.equal(b.content.children.length,10);assert.equal(b.content.columns,2);for(const right of b.content.children.filter((_,i)=>i%2))assert.equal(right.children.length,3);}}
 if(cause==='tax-paired'){const b=block(repaired('earning-money-v1'),'p61-example-block');assert.equal(b.content.children.length,8);assert.deepEqual(b.content.children.filter((_,i)=>i%2).slice(1).map(x=>x.prompt.blocks[0].rowHeights[0]),[28,54,32]);assert.ok(b.content.children.filter((_,i)=>i%2).slice(1).every(x=>x.prompt.blocks[0].border===false));}
 if(cause==='response-labels'){const b=block(repaired('length-v1'),'p45-diameter-turn-block'),labels=teachingLabels([b]);assert.equal(labels['p45-diameter-turn'],'');assert.deepEqual([1,2,3].map(n=>labels['p45-diameter-turn-step'+n]),['1','2','3']);const old=structuredClone(b);delete old.presentation.sourceResponseLabels;assert.notDeepEqual(teachingLabels([old]),labels,'absence retains legacy lettering');}
 if(cause==='regular-grid'){const p=repaired('operations-fractions-decimals-v1'),b=block(p,'p27-q2');assert.deepEqual(b.content.children.map(x=>x.label),['a','e','i','b','f','j','c','g','k','d','h','l']);assert.equal(p.settings.layoutOverrides.blockLayouts[b.id]?.arrangement,undefined);assert.equal(b.presentation.layoutOverrides.blockLayouts[b.id]?.arrangement,undefined);}
 if(cause==='paired-borders-scoped'){const b=block(repaired('area-parallelograms-triangles-v1'),'p43-side-length-activity');assert.equal(b.content.prompt.blocks[0].border,false);assert.deepEqual(b.content.children,block(fixtures['area-parallelograms-triangles-v1'],b.id).content.children,'meaningful scaffold tables unchanged');}
 if(cause==='decorative-inner-box'){const p=repaired('earning-money-v1');assert.ok(block(p,'p13-total-pay-formulas').content.blocks.every(x=>x.type==='paragraph'));assert.deepEqual(block(p,'p13-pay-example-group'),block(fixtures[p.id],'p13-pay-example-group'),'purposeful Lily box retained');}
 if(cause==='formula-alignment'||cause==='mean-alignment'){const id=projects[0],p=repaired(id),b=block(p,cause==='formula-alignment'?'p13-total-pay-formulas':'p37-example');visit(b,n=>{if(n.type==='math')katex.renderToString(n.latex,{throwOnError:true});});if(cause==='mean-alignment')assert.deepEqual(b.examples.map(e=>e.questionDiagrams),block(fixtures[id],b.id).examples.map(e=>e.questionDiagrams),'graph interleaving/dependencies preserved');}
 if(cause==='given-working'){const p=repaired('earning-money-v1'),b=block(p,'p13-pay-example-group');for(const name of ['normal','overtime','total']){const m=find(b.content,'p13-lily-'+name+'-working').inlines[0];assert.ok(m.latex.includes('\\color{#24282d}'));assert.ok(m.latex.includes('\\color{#268cff}'));katex.renderToString(m.latex,{throwOnError:true});}assert.deepEqual(block(p,'p27-example-header'),block(fixtures[p.id],'p27-example-header'),'correct independent commission calculations untouched');}
 if(cause==='square-root-working'){const b=block(repaired('simple-quadratic-equations-v1'),'p4-example-block');for(const e of b.examples){assert.ok(e.prompt.blocks[1].inlines[0].latex.includes('='));assert.equal(e.equationAlignment.mode,'relation');assert.deepEqual(e.theorySolution,block(fixtures['simple-quadratic-equations-v1'],b.id).examples.find(x=>x.id===e.id).theorySolution);}}
 if(cause==='duplicate-worked-diagram'){const b=block(repaired('circle-trigonometry-v1'),'p53-determine');for(const e of b.examples){assert.equal(e.solutionDiagrams[0].overlayOf,e.questionDiagrams[0].id);assert.ok(combinedExampleTikz(e.questionDiagrams[0],e.solutionDiagrams[0]));}}
 });
}
